"use strict";Gordic.Previews.register("sml:Doklad",{render:function(e,r){var o=$(e);o.empty().append("<h3 class='g-state-text g-state-active' style='margin: 0.5rem;'>Akce '"+r.nazev+"'</h3><hr style='margin: 0.5rem; opacity: 0.2;'/>"),$("<div class='gform--view-mode'>").appendTo(o).gform("setup",{layoutDescriptor:"L1M1S1, breaks-300-400"}).gformsection("create").gpidbar({pid:r.ixp}).gformsection("create").gformrow("addFieldsRow","Agendové číslo").gformtext(r.ac_sml,"bold").gformrow("addFieldsRow","Evidenční číslo").gformtext(r.ac,"bold")}});